const firstLesson = [
 [
 ['The ECG records voltage differences', 'Start with what the instrument actually records. Two skin locations can be at different electrical potentials. The ECG follows how that difference changes as electrical activity spreads through the heart. So when you look at a tracing, think of a changing electrical signal rather than a picture of the heart squeezing.'],
 ['Electrical activity does not measure pumping', 'Suppose the tracing looks organised. Can that alone tell us the cardiac output? No. The surface ECG does not directly measure contraction force, cardiac output or coronary blood flow. Electrical activation normally precedes contraction, but recognising an electrical pattern is different from demonstrating effective mechanical output. Keep that distinction in mind when naming every wave.'],
 ['Depolarisation activates; repolarisation restores', 'These words describe changes in the electrical state of myocardial cells. Depolarisation is associated with activation; repolarisation restores the electrical state afterwards. The waveform depends on when these processes happen and the direction in which they spread. We will now connect that sequence to the familiar letters on the tracing.']
 ],
 [
 ['Atrial depolarisation → P wave', 'Follow the impulse from its usual starting point: the sinus node. It spreads through atrial myocardium. That atrial electrical activation produces the P wave. Notice the wording: atrial depolarisation. Calling P simply an atrial contraction would confuse the electrical event with the mechanical event that follows.'],
 ['AV delay, then rapid ventricular activation', 'After the atria activate, the impulse reaches the atrioventricular conduction system. Conduction is delayed before rapid activation through the His–Purkinje network. Think of this as an ordered sequence rather than a collection of unrelated wave shapes. The delay comes before the main ventricular activation.'],
 ['Ventricular depolarisation → QRS', 'Now the ventricular myocardium activates. Its changing electrical potentials generate the QRS complex. Try the course example: what process produces QRS? The precise answer is ventricular depolarisation. It is not a direct measurement of how forcefully the ventricles contract.'],
 ['Ventricular repolarisation → T wave', 'Electrical recovery of the ventricles contributes to the T wave. The atria also repolarise, but that signal is usually obscured by the much larger ventricular complex. A missing separate atrial recovery wave therefore does not mean the atria have no repolarisation. Before continuing, link each item aloud: P, QRS, T.']
 ],
 [
 ['PR: P onset to QRS onset', 'Place one boundary at the beginning of P and the other at the beginning of QRS. Everything between those boundaries belongs to the PR interval. This includes atrial activation as well as conduction towards the ventricles. That is why describing the entire PR interval as AV nodal delay alone is too narrow.'],
 ['PR segment is only part of the interval', 'Compare the two names carefully. The PR segment is after the P wave and before QRS; the PR interval starts earlier, at P onset. The segment and interval therefore have different boundaries. When measuring, name which one you mean before placing your markers.'],
 ['An organised ECG does not prove effective output', 'Bring the lesson back to its central distinction. Electrical and mechanical events are linked, but they are not identical. Activation precedes contraction, and a tracing alone does not establish effective pumping. Check your understanding: can you explain P, QRS and T as electrical events without substituting the word contraction?']
 ]
];
export function teachingPoints(o,sections){return sections.flatMap(s=>{
 const point=(cue,text,i=0)=>({...s,key:s.key+'@'+i,sourceKey:s.key,board:cue,text,point:i});
 if(o.id==='lead-theory-01'&&s.key.startsWith('principle-'))return firstLesson[Number(s.key.slice(10))].map(([cue,text],i)=>point(cue,text,i));
 if(s.key.startsWith('principle-'))return [point(boardCues[o.id]?.[Number(s.key.slice(10))]||s.title,s.text)];
 if(s.key==='introduction')return[point(o.title,`Let’s begin with this goal: ${o.title}. ${o.why} We will build the explanation one point at a time.`,0)];
 if(s.key==='steps')return o.steps.map((x,i)=>point(x.title,x.text,i));
 if(s.key==='pitfalls')return o.pitfalls.map((x,i)=>point('Avoid this interpretation trap',x,i));
 if(s.key==='example')return[point('Start with the question',o.example.question),...o.example.working.map((x,i)=>point('Working · '+(i+1),x,i+1)),point('Worked answer',o.example.answer,o.example.working.length+1)];
 if(s.key==='guided')return[point('Your turn: think before revealing the answer',o.guidedExercise.prompt),...o.guidedExercise.steps.map((x,i)=>point('Guided step '+(i+1),x,i+1)),point('Compare your reasoning',o.guidedExercise.answer+' '+o.guidedExercise.explanation,o.guidedExercise.steps.length+1)];
 if(s.key.startsWith('depth-')){const text=o.deepDive[Number(s.key.slice(6))].text;const sentences=text.match(/[^.!?]+(?:[.!?](?=\s|$)|$)/g)||[text];const groups=[];let group='';for(const sentence of sentences){if(group&&group.split(/\s+/).length>45){groups.push(group.trim());group=''}group+=sentence+' '}if(group.trim())groups.push(group.trim());return groups.map((text,i)=>point(s.title+(groups.length>1?' · focus '+(i+1):''),text,i))}
 return[point(s.key==='summary'?'Can you explain it in your own words?':s.title,s.text)];
 })}
