 function focusBoardLabels(){const x=explanation;if(!x)return;const svg=$('#board-teaching .visual svg');if(!svg)return;svg.querySelectorAll('.tutor-label-active').forEach(e=>e.classList.remove('tutor-label-active'));svg.querySelector('.tutor-board-pointer')?.remove();const labels=x.labelBatches[x.index]||[];for(const label of labels){label.style.visibility='visible';label.classList.add('tutor-label-active')}const target=labels.at(-1);if(!target)return;const box=target.getBBox?.()||{x:Number(target.getAttribute('x')),y:Number(target.getAttribute('y'))-20,width:100,height:24},g=document.createElementNS('http://www.w3.org/2000/svg','g');g.setAttribute('class','tutor-board-pointer');g.setAttribute('aria-hidden','true');g.innerHTML=`<circle cx="${box.x+box.width+9}" cy="${box.y+box.height/2}" r="3" fill="var(--accent)"/>`;svg.append(g)}
