 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('[data-classroom].board-focus')){$('[data-classroom]').classList.remove('board-focus');const b=$('[data-class-action=focus]');b.textContent='Enlarge board';b.setAttribute('aria-pressed','false');requestAnimationFrame(redraw)}});window.addEventListener('resize',()=>requestAnimationFrame(redraw));document.addEventListener('toggle',e=>{if(e.target.id==='earlier-explanation')requestAnimationFrame(redraw)},true);window.addEventListener('pagehide',()=>{cancelTeaching();resize?.disconnect()});window.addEventListener('ecg:render',enter);return{enter};
